diff --git a/packages/workflow/src/workflow-data-proxy.ts b/packages/workflow/src/workflow-data-proxy.ts
index aa2721197..65ddce9fb 100644
--- a/packages/workflow/src/workflow-data-proxy.ts
+++ b/packages/workflow/src/workflow-data-proxy.ts
@@ -199,7 +199,28 @@ export class WorkflowDataProxy {
 				get(_, name) {
 					if (name === 'isProxy') return true;
 					name = name.toString();
-					return that.selfData[name];
+					const value = that.selfData[name];
+
+					if (typeof value === 'string' && value.charAt(0) === '=') {
+						// The value is an expression so resolve it. selfData is not passed on
+						// to avoid infinite recursion on self-referencing values.
+						return that.workflow.expression.getParameterValue(
+							value,
+							that.runExecutionData,
+							that.runIndex,
+							that.itemIndex,
+							that.activeNodeName,
+							that.connectionInputData,
+							that.mode,
+							that.additionalKeys,
+							that.executeData,
+							false,
+							{},
+							that.contextNodeName,
+						);
+					}
+
+					return value;
 				},
 			},
 		);
