@@ -2078,4 +2079,45 @@ describe('WorkflowDataProxy', () => {
 			expect(proxy.$('Edit').item.json.test).toBe('1111');
 		});
 	});
+
+	describe('$self', () => {
+		const getSelfProxy = (selfData: IDataObject) => {
+			const fixture = loadFixture('base');
+			return new WorkflowDataProxy(
+				new Workflow({
+					id: '123',
+					name: 'test workflow',
+					nodes: fixture.workflow.nodes,
+					connections: fixture.workflow.connections,
+					active: false,
+					nodeTypes: Helpers.NodeTypes(),
+				}),
+				null,
+				0,
+				0,
+				'Edit Fields',
+				[],
+				{},
+				'integrated',
+				{},
+				undefined,
+				-1,
+				selfData,
+			).getDataProxy();
+		};
+
+		test('returns plain values as is', () => {
+			expect(getSelfProxy({ host: 'example.com' }).$self.host).toBe('example.com');
+		});
+
+		test('resolves expression-mode values', () => {
+			const proxy = getSelfProxy({ host: '={{ "ex" + "ample.com" }}' });
+			expect(proxy.$self.host).toBe('example.com');
+		});
+
+		test('does not recurse infinitely on self-referencing values', () => {
+			const proxy = getSelfProxy({ a: '={{ $self.a }}' });
+			expect(() => proxy.$self.a).not.toThrow(/call stack/);
+		});
+	});
 });
